--- components/site-wordmark.tsx	
+++ components/site-wordmark.tsx	
@@ -1,184 +1,189 @@
 "use client";

-import { useId } from "react";
+import {
+  motion,
+  useMotionValue,
+  useReducedMotion,
+  useSpring,
+  useTransform,
+} from "motion/react";
+import { useId, type MouseEvent as ReactMouseEvent } from "react";

 /** The same plate-scale canvas as the reference footer graphic. */
 const VIEWBOX_WIDTH = 1410;
 const VIEWBOX_HEIGHT = 258;
 const CELL_HEIGHT = 48;
 const TRACKING = 1;
+const SPRING = { stiffness: 150, damping: 25 } as const;

 /**
  * Five-row orthogonal glyphs, cut lowercase. The cells are only a layout
  * source. At render time, adjacent cells share edges, so the SVG draws one
  * clean outline instead of a stack of rounded rectangles.
  *
  * Row one is the ascender line and rows two to five are the x-height, so `d`
  * and `h` stand a row above everything else — which is the whole of what makes
- * a word read as lowercase rather than as small capitals. The `2` uses all
- * five rows, with the same open contour rhythm as the letters.
+ * a word read as lowercase rather than as small capitals. The `2` is cut as an
+ * old-style figure, sitting on the x-height with the letters, because a lining
+ * figure in the middle of a lowercase word is a capital by another name.
  */
 const GLYPHS: Readonly<Record<string, readonly string[]>> = {
   a: [".....", ".####", "#...#", "#...#", ".####"],
   d: ["....#", ".####", "#...#", "#...#", ".####"],
   h: ["#....", "#####", "#...#", "#...#", "#...#"],
   m: [".....", "#####", "#.#.#", "#.#.#", "#.#.#"],
   r: [".....", "#.###", "##...", "#....", "#...."],
   s: [".....", ".####", "##...", "...##", "####."],
   u: [".....", "#...#", "#...#", "#...#", ".####"],
   v: [".....", "#...#", "#...#", ".#.#.", "..#.."],
-  "2": [".###.", "#...#", "...#.", "..#..", "#####"],
+  "2": [".....", ".###.", "#...#", ".##..", "#####"],
 };

 type Cell = { x: number; y: number };

 function layout(text: string) {
   const cells: Cell[] = [];
   let cursor = 0;

   for (const char of text) {
     const glyph = GLYPHS[char];
     if (!glyph) continue;

     for (let y = 0; y < glyph.length; y++) {
       for (let x = 0; x < glyph[y].length; x++) {
         if (glyph[y][x] === "#") cells.push({ x: cursor + x, y });
       }
     }

     cursor += glyph[0].length + TRACKING;
   }

   return {
     cells,
     columns: Math.max(cursor - TRACKING, 1),
   };
 }

 function formatCoordinate(value: number) {
   return value.toFixed(3).replace(/\.?(0+)$/, "");
 }

 function buildPaths(cells: Cell[], columns: number) {
   const cellWidth = (VIEWBOX_WIDTH - 2) / columns;
   const occupied = new Set(cells.map((cell) => `${cell.x}:${cell.y}`));
   const fill: string[] = [];
   const outline: string[] = [];

   for (const cell of cells) {
     const x0 = 1 + cell.x * cellWidth;
     const x1 = 1 + (cell.x + 1) * cellWidth;
     const y0 = 1 + cell.y * CELL_HEIGHT;
     const y1 = y0 + CELL_HEIGHT;
     const x = formatCoordinate(x0);
     const right = formatCoordinate(x1);
     const y = formatCoordinate(y0);
     const bottom = formatCoordinate(y1);

     fill.push(`M${x} ${y}H${right}V${bottom}H${x}Z`);

     if (!occupied.has(`${cell.x}:${cell.y - 1}`)) {
       outline.push(`M${x} ${y}H${right}`);
     }
     if (!occupied.has(`${cell.x + 1}:${cell.y}`)) {
